('eigo_lv3_001', 3, 'eigo', '「3番目」を表す英語として正しいつづりはどれ？', 'third', 'threeth', 'therd', 'thirty', 'thirteen', 'three', '3番目は third。first（1番目）・second（2番目）と同じく、もとの数とは形が大きく変わる語です。', 0, 1),
('eigo_lv3_002', 3, 'eigo', '「5番目」を表す英語として正しいつづりはどれ？', 'fifth', 'fiveth', 'fivth', 'fifty', 'fiftth', 'fifteen', '5番目は fifth。five の ve が f に変わって th がつきます。fiveth とは書きません。', 0, 1),
('eigo_lv3_003', 3, 'eigo', '「9番目」を表す英語として正しいつづりはどれ？', 'ninth', 'nineth', 'ninety', 'nineteen', 'ninenth', 'nainth', '9番目は ninth。nine の最後の e を取ってから th をつけます。nineth はよくある書きまちがいです。', 0, 1),
('eigo_lv3_004', 3, 'eigo', '「12番目」を表す英語として正しいつづりはどれ？', 'twelfth', 'twelveth', 'twelvth', 'twelth', 'twentieth', 'twelve', '12番目は twelfth。twelve の ve が f に変わって th がつきます。', 0, 1),
('eigo_lv3_005', 3, 'eigo', '「21st」の読み方として正しいものはどれ？', 'twenty-first', 'twenty-one', 'twenty-oneth', 'twentieth-one', 'twenty-firsth', 'twelve-first', '21番目は twenty-first。十の位はそのままで、一の位だけを first（1番目）にします。', 0, 1),
('eigo_lv3_006', 3, 'eigo', '英語の second には「2番目の」のほかに、どんな意味がある？', '秒', '分', '時間', '週', '日', '年', 'second には「秒」という意味もあります。Wait a second.（ちょっと待って）のように使います。分は minute です。', 0, 1),
('eigo_lv3_007', 3, 'eigo', '次のうち「〜番目」という順番を表す語はどれ？', 'eighth', 'eight', 'eighty', 'eighteen', 'weight', 'height', 'eighth は「8番目」。eight（8）・eighty（80）・eighteen（18）は数そのものを表す語です。', 0, 1),
('eigo_lv3_008', 3, 'eigo', '「13番目」を数字と文字で短く書くと、どれが正しい？', '13th', '13rd', '13st', '13nd', '13td', '13ed', '3番目は 3rd ですが、13番目は thirteenth なので 13th と書きます。11th・12th も同じです。', 0, 1),
('eigo_lv3_009', 3, 'eigo', '「22番目」を数字と文字で短く書くと、どれが正しい？', '22nd', '22th', '22st', '22rd', '22ed', '22td', '22番目は twenty-second なので 22nd。一の位が2のときは nd をつけます（12番目は例外で 12th）。', 0, 1),
('eigo_lv3_010', 3, 'eigo', '「I''m in the sixth grade.」の意味は？', '私は6年生です。', '私は6さいです。', '私は6組です。', '私は6人家族です。', '私は6時に起きます。', '私は6番目に来ました。', 'grade は「学年」。sixth は「6番目」なので、in the sixth grade で「6年生」です。', 0, 1),
('eigo_lv3_011', 3, 'eigo', '「expensive（値段が高い）」の反対の意味の語はどれ？', 'cheap', 'high', 'heavy', 'tall', 'deep', 'happy', 'expensive（値段が高い）の反対は cheap（安い）。high は「高さが高い」、tall は「背が高い」です。', 0, 1),
('eigo_lv3_012', 3, 'eigo', '「early（早く）」の反対の意味の語はどれ？', 'late', 'fast', 'slow', 'soon', 'near', 'easy', 'early（時間が早く）の反対は late（おそく）。fast（速く）の反対は slow で、別の組み合わせです。', 0, 1),
('eigo_lv3_013', 3, 'eigo', '「heavy（重い）」の反対の意味の語はどれ？', 'light', 'right', 'high', 'white', 'tight', 'weight', 'heavy（重い）の反対は light（軽い）。light には「光・明るい」という意味もあります。', 0, 1),
('eigo_lv3_014', 3, 'eigo', '「same（同じ）」の反対の意味の語はどれ？', 'different', 'difficult', 'delicious', 'dangerous', 'distant', 'similar', 'same（同じ）の反対は different（ちがう）。similar は「よく似た」で、反対の意味ではありません。', 0, 1),
('eigo_lv3_015', 3, 'eigo', '「remember（覚えている）」の反対の意味の語はどれ？', 'forget', 'forgive', 'remind', 'return', 'repeat', 'review', 'remember（覚えている）の反対は forget（忘れる）。forgive は「許す」で、つづりが似ているので注意。', 0, 1),
('eigo_lv3_016', 3, 'eigo', '「win（勝つ）」の反対の意味の語はどれ？', 'lose', 'loose', 'last', 'leave', 'live', 'love', 'win（勝つ）の反対は lose（負ける）。loose は「ゆるい」という別の語です。', 0, 1),
('eigo_lv3_017', 3, 'eigo', '「dangerous（危険な）」の反対の意味の語はどれ？', 'safe', 'save', 'sure', 'soft', 'sick', 'same', 'dangerous（危険な）の反対は safe（安全な）。save は「救う・たくわえる」という動詞です。', 0, 1),
('eigo_lv3_018', 3, 'eigo', '「push（おす）」の反対の意味の語はどれ？', 'pull', 'put', 'pool', 'pick', 'pass', 'pour', 'push（おす）の反対は pull（引く）。ドアに PUSH や PULL と書かれていることがあります。', 0, 1),
('eigo_lv3_019', 3, 'eigo', '「borrow（借りる）」の反対の意味の語はどれ？', 'lend', 'buy', 'bring', 'bend', 'send', 'land', 'borrow（借りる）の反対は lend（貸す）。bring は「持ってくる」、send は「送る」です。', 0, 1),
('eigo_lv3_020', 3, 'eigo', '「noisy（うるさい）」の反対の意味の語はどれ？', 'quiet', 'quite', 'quick', 'quit', 'quiz', 'queen', 'noisy（うるさい）の反対は quiet（静かな）。quite（かなり）とつづりが似ているので注意。', 0, 1),
('eigo_lv3_021', 3, 'eigo', '「strong（強い）」の反対の意味の語はどれ？', 'weak', 'week', 'wake', 'wide', 'wet', 'well', 'strong（強い）の反対は weak（弱い）。week（週）と発音は同じですが、つづりと意味がちがいます。', 0, 1),
